FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT := 0;
    status       : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    head         : DINT := 1;
    tail         : DINT := 1;
    prevEnqueue  : BOOL := FALSE;
    prevDequeue  : BOOL := FALSE;
    prevReset    : BOOL := FALSE;
END_VAR

    // Rising edge detection
    IF reset AND NOT prevReset THEN
        // Reset takes highest priority
        head         := 1;
        tail         := 1;
        elementCount := 0;
        status       := 16#0000;
    ELSIF enqueue AND NOT prevEnqueue THEN
        // Enqueue: only on rising edge, when queue is not full
        IF elementCount >= capacity THEN
            status := 16#8002;
        ELSE
            buffer[tail] := item;
            tail := (tail MOD capacity) + 1;
            elementCount := elementCount + 1;
            status := 16#0000;
        END_IF
    ELSIF dequeue AND NOT prevDequeue THEN
        // Dequeue: only on rising edge, when queue is not empty
        IF elementCount = 0 THEN
            status := 16#8001;
        ELSE
            item := buffer[head];
            head := (head MOD capacity) + 1;
            elementCount := elementCount - 1;
            status := 16#0000;
        END_IF
    ELSE
        status := 16#0000;
    END_IF

    prevEnqueue := enqueue;
    prevDequeue := dequeue;
    prevReset   := reset;
END_FUNCTION_BLOCK
